changeSet.sql:
DROP SCHEMA IF EXISTS dm_test CASCADE;
CREATE SCHEMA dm_test;

CREATE TABLE dm_test.plain_rows (
    a text NOT NULL, b text NOT NULL, c bytea NOT NULL,
    n integer NOT NULL DEFAULT 0, touched_by text,
    PRIMARY KEY (a, b, c)
) WITH (autovacuum_enabled = false);
INSERT INTO dm_test.plain_rows (a, b, c)
SELECT 'a' || (g % 97), 'b' || g, decode(lpad(to_hex(g), 8, '0'), 'hex')
  FROM generate_series(1, 100000) g;

CREATE TABLE dm_test.tenant_rows (
    tenant_id text NOT NULL, id bigint NOT NULL, payload text,
    n integer NOT NULL DEFAULT 0, touched_by text,
    PRIMARY KEY (tenant_id, id)
);
ALTER TABLE dm_test.tenant_rows ENABLE ROW LEVEL SECURITY;
ALTER TABLE dm_test.tenant_rows FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON dm_test.tenant_rows
    USING (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));
CREATE POLICY owner_read ON dm_test.tenant_rows FOR SELECT TO nexus_admin_dmlutils USING (true);
INSERT INTO dm_test.tenant_rows (tenant_id, id, payload)
SELECT t, g, 'p' || g FROM unnest(ARRAY['default', 'acme', 'globex', 'orphan']) t, generate_series(1, 200) g;

CREATE TABLE dm_test.leafed (
    model text NOT NULL, tenant_id text NOT NULL, id bigint NOT NULL, payload text,
    n integer NOT NULL DEFAULT 0, touched_by text,
    PRIMARY KEY (model, tenant_id, id)
) PARTITION BY LIST (model);
DO $$
DECLARE m text; t text; part text; leaf text;
BEGIN
    FOREACH m IN ARRAY ARRAY['m1', 'm2'] LOOP
        part := 'leafed_' || m;
        EXECUTE format('CREATE TABLE dm_test.%I PARTITION OF dm_test.leafed FOR VALUES IN (%L) PARTITION BY LIST (tenant_id)', part, m);
        FOREACH t IN ARRAY ARRAY['default', 'acme', 'globex'] LOOP
            leaf := part || '_' || t;
            EXECUTE format('CREATE TABLE dm_test.%I PARTITION OF dm_test.%I FOR VALUES IN (%L)', leaf, part, t);
            EXECUTE format('ALTER TABLE dm_test.%I ENABLE ROW LEVEL SECURITY', leaf);
            EXECUTE format('ALTER TABLE dm_test.%I FORCE ROW LEVEL SECURITY', leaf);
            EXECUTE format('CREATE POLICY tenant_isolation ON dm_test.%I USING (tenant_id = current_setting(%L, true)) WITH CHECK (tenant_id = current_setting(%L, true))',
                           leaf, 'nexus.tenant', 'nexus.tenant');
            EXECUTE format('CREATE POLICY owner_read ON dm_test.%I FOR SELECT TO nexus_admin_dmlutils USING (true)', leaf);
            EXECUTE format('INSERT INTO dm_test.leafed (model, tenant_id, id, payload) SELECT %L, %L, g, ''p'' || g FROM generate_series(1, 150) g', m, t);
        END LOOP;
    END LOOP;
END $$;
ALTER TABLE dm_test.leafed ENABLE ROW LEVEL SECURITY;
ALTER TABLE dm_test.leafed FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON dm_test.leafed
    USING (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));
CREATE POLICY owner_read ON dm_test.leafed FOR SELECT TO nexus_admin_dmlutils USING (true);

DO $$
DECLARE r record;
BEGIN
    FOR r IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
              WHERE n.nspname = 'dm_test' AND c.relkind IN ('r', 'p') LOOP
        EXECUTE format('ALTER TABLE dm_test.%I OWNER TO nexus_admin_dmlutils', r.relname);
    END LOOP;
END $$;
ALTER SCHEMA dm_test OWNER TO nexus_admin_dmlutils;
